import { useEffect, useState } from "react";
import API from "../api/api";
import "../styles/vote.css";

function Vote() {
  const [elections, setElections] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [electionId, setElectionId] = useState("");
  const [candidateId, setCandidateId] = useState("");

  useEffect(() => {
    API.get("/api/election").then(res => {
      setElections(res.data);
    });
  }, []);

  const loadCandidates = async (id) => {
    setElectionId(id);
    const res = await API.get(`/api/candidate/${id}`);
    setCandidates(res.data);
  };

  const submitVote = async () => {
    try {
      await API.post("/api/vote", {
        electionId,
        candidateId
      });

      alert("Vote submitted successfully!");
    } catch (err) {
      alert("You already voted or error occurred");
    }
  };

  return (
    <div className="vote-box">
      <h2>Vote</h2>

      <select onChange={(e) => loadCandidates(e.target.value)}>
        <option>Select Election</option>
        {elections.map(e => (
          <option key={e.id} value={e.id}>
            {e.title}
          </option>
        ))}
      </select>

      <select onChange={(e) => setCandidateId(e.target.value)}>
        <option>Select Candidate</option>
        {candidates.map(c => (
          <option key={c.id} value={c.id}>
            {c.name}
          </option>
        ))}
      </select>

      <button onClick={submitVote}>Submit Vote</button>
    </div>
  );
}

export default Vote;
